"use client"

import { useRef, useEffect, useCallback } from "react"

interface Particle {
    x: number
    y: number
    vx: number
    vy: number
    size: number
    baseX: number
    baseY: number
}

export function InteractiveParticleBackground() {
    const canvasRef = useRef<HTMLCanvasElement>(null)
    const mouseRef = useRef({ x: 0, y: 0, isActive: false })
    const particlesRef = useRef<Particle[]>([])
    const animationRef = useRef<number>(0)

    const initParticles = useCallback((canvas: HTMLCanvasElement) => {
        const particles: Particle[] = []
        const particleCount = Math.floor((canvas.width * canvas.height) / 12000)

        for (let i = 0; i < particleCount; i++) {
            const x = Math.random() * canvas.width
            const y = Math.random() * canvas.height
            particles.push({
                x,
                y,
                vx: (Math.random() - 0.5) * 0.5,
                vy: (Math.random() - 0.5) * 0.5,
                size: Math.random() * 2 + 1,
                baseX: x,
                baseY: y,
            })
        }
        particlesRef.current = particles
    }, [])

    useEffect(() => {
        const canvas = canvasRef.current
        if (!canvas) return

        const ctx = canvas.getContext("2d")
        if (!ctx) return

        const resize = () => {
            const container = canvas.parentElement
            if (container) {
                canvas.width = container.offsetWidth
                canvas.height = container.offsetHeight
                initParticles(canvas)
            }
        }

        const handleMouseMove = (e: MouseEvent) => {
            const rect = canvas.getBoundingClientRect()
            mouseRef.current = {
                x: e.clientX - rect.left,
                y: e.clientY - rect.top,
                isActive: true,
            }
        }

        const handleMouseLeave = () => {
            mouseRef.current.isActive = false
        }

        const animate = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height)
            const particles = particlesRef.current
            const mouse = mouseRef.current

            // Update and draw particles
            particles.forEach((particle) => {
                // Basic movement
                particle.x += particle.vx
                particle.y += particle.vy

                // Bounce off edges
                if (particle.x < 0 || particle.x > canvas.width) {
                    particle.vx *= -1
                    particle.x = Math.max(0, Math.min(canvas.width, particle.x))
                }
                if (particle.y < 0 || particle.y > canvas.height) {
                    particle.vy *= -1
                    particle.y = Math.max(0, Math.min(canvas.height, particle.y))
                }

                // Mouse interaction - particles are attracted/repelled by cursor
                if (mouse.isActive) {
                    const dx = mouse.x - particle.x
                    const dy = mouse.y - particle.y
                    const distance = Math.sqrt(dx * dx + dy * dy)
                    const maxDistance = 150

                    if (distance < maxDistance) {
                        // Repel particles away from cursor
                        const force = (maxDistance - distance) / maxDistance
                        particle.vx -= (dx / distance) * force * 0.5
                        particle.vy -= (dy / distance) * force * 0.5
                    }
                }

                // Add some friction to slow particles down
                particle.vx *= 0.99
                particle.vy *= 0.99

                // Gentle drift back to base position
                particle.vx += (particle.baseX - particle.x) * 0.0001
                particle.vy += (particle.baseY - particle.y) * 0.0001
            })

            // Draw connections between nearby particles
            const maxConnectionDistance = 120
            ctx.lineWidth = 0.5

            for (let i = 0; i < particles.length; i++) {
                for (let j = i + 1; j < particles.length; j++) {
                    const dx = particles[i].x - particles[j].x
                    const dy = particles[i].y - particles[j].y
                    const distance = Math.sqrt(dx * dx + dy * dy)

                    if (distance < maxConnectionDistance) {
                        const opacity = (1 - distance / maxConnectionDistance) * 0.3
                        ctx.strokeStyle = `rgba(249, 115, 22, ${opacity})`
                        ctx.beginPath()
                        ctx.moveTo(particles[i].x, particles[i].y)
                        ctx.lineTo(particles[j].x, particles[j].y)
                        ctx.stroke()
                    }
                }

                // Draw connection to mouse cursor
                if (mouse.isActive) {
                    const dx = mouse.x - particles[i].x
                    const dy = mouse.y - particles[i].y
                    const distance = Math.sqrt(dx * dx + dy * dy)

                    if (distance < 150) {
                        const opacity = (1 - distance / 150) * 0.5
                        ctx.strokeStyle = `rgba(249, 115, 22, ${opacity})`
                        ctx.beginPath()
                        ctx.moveTo(particles[i].x, particles[i].y)
                        ctx.lineTo(mouse.x, mouse.y)
                        ctx.stroke()
                    }
                }
            }

            // Draw particles
            particles.forEach((particle) => {
                ctx.beginPath()
                ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2)
                ctx.fillStyle = "rgba(249, 115, 22, 0.6)"
                ctx.fill()
            })

            animationRef.current = requestAnimationFrame(animate)
        }

        resize()
        window.addEventListener("resize", resize)
        canvas.addEventListener("mousemove", handleMouseMove)
        canvas.addEventListener("mouseleave", handleMouseLeave)
        animate()

        return () => {
            window.removeEventListener("resize", resize)
            canvas.removeEventListener("mousemove", handleMouseMove)
            canvas.removeEventListener("mouseleave", handleMouseLeave)
            cancelAnimationFrame(animationRef.current)
        }
    }, [initParticles])

    return (
        <canvas
            ref={canvasRef}
            className="fixed inset-0 w-full h-full pointer-events-auto z-0"
            style={{ opacity: 0.7 }}
        />
    )
}
