// Animated arrow SVG component
function AnimatedArrow({
    startX,
    startY,
    endX,
    endY,
    delay,
    color
}: {
    startX: number
    startY: number
    endX: number
    endY: number
    delay: number
    color: string
}) {
    // Calculate control point for curved line
    const midX = (startX + endX) / 2
    const midY = (startY + endY) / 2

    // Add curve based on direction
    const curveOffset = 30
    const path = `M ${startX} ${startY} Q ${midX} ${midY - curveOffset} ${endX} ${endY}`

    return (
        <motion.g
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.8, delay }}
        >
            {/* Glow effect */}
            <motion.path
                d={path}
                fill="none"
                stroke={color}
                strokeWidth="4"
                strokeLinecap="round"
                filter="url(#glow)"
                initial={{ pathLength: 0 }}
                animate={{ pathLength: 1 }}
                transition={{ duration: 1.2, delay, ease: "easeInOut" }}
            />
            {/* Main line */}
            <motion.path
                d={path}
                fill="none"
                stroke={color}
                strokeWidth="2"
                strokeLinecap="round"
                initial={{ pathLength: 0 }}
                animate={{ pathLength: 1 }}
                transition={{ duration: 1.2, delay, ease: "easeInOut" }}
            />
            {/* Animated dot along path */}
            <motion.circle
                r="4"
                fill={color}
                filter="url(#glow)"
                initial={{ offsetDistance: "0%" }}
                animate={{ offsetDistance: "100%" }}
                transition={{
                    duration: 2,
                    delay: delay + 0.5,
                    repeat: Infinity,
                    ease: "linear"
                }}
                style={{ offsetPath: `path('${path}')` }}
            />
        </motion.g>
    )
}

export function BackendModulesSection() {
    const ref = useRef(null)
    const isInView = useInView(ref, { once: true, margin: "-100px" })
    const [dimensions, setDimensions] = useState({ width: 800, height: 600 })

    useEffect(() => {
        const updateDimensions = () => {
            if (ref.current) {
                const rect = (ref.current as HTMLElement).getBoundingClientRect()
                setDimensions({ width: rect.width, height: Math.min(rect.height, 700) })
            }
        }
        updateDimensions()
        window.addEventListener("resize", updateDimensions)
        return () => window.removeEventListener("resize", updateDimensions)
    }, [])

    // Calculate arrow positions
    const centerX = dimensions.width / 2
    const centerY = dimensions.height / 2
    const moduleRadius = Math.min(dimensions.width, dimensions.height) * 0.35

    return (
        <section ref={ref} className="py-24 relative overflow-hidden min-h-[800px] bg-background">
            {/* Tangle particle background */}
            <TangleParticleBackground />

            {/* Dark overlay gradient */}
            <div className="absolute inset-0 bg-gradient-to-b from-background via-background/90 to-background" />

            <div className="container mx-auto px-4 relative">
                {/* Section header */}
                <div className="text-center mb-16">
                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        animate={isInView ? { opacity: 1, y: 0 } : {}}
                        transition={{ duration: 0.6 }}
                    >
                        <span className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-primary/10 border border-primary/20 text-sm font-medium text-primary mb-4">
                            <Cpu className="h-4 w-4" />
                            BACKEND ARCHITECTURE
                        </span>
                        <h2 className="font-display text-3xl md:text-5xl font-bold mb-4">
                            The <span className="text-gradient">Four Pillars</span> of AURA
                        </h2>
                        <p className="text-lg text-muted-foreground max-w-2xl mx-auto">
                            Our autonomous AI backend processes millions of claims through four specialized modules
                        </p>
                    </motion.div>
                </div>

                {/* Modules visualization */}
                <div className="relative h-[600px] max-w-4xl mx-auto">
                    {/* SVG for arrows */}
                    <svg
                        className="absolute inset-0 w-full h-full pointer-events-none"
                        viewBox={`0 0 ${dimensions.width} ${dimensions.height}`}
                        preserveAspectRatio="xMidYMid meet"
                    >
                        <defs>
                            <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                                <feGaussianBlur stdDeviation="3" result="coloredBlur" />
                                <feMerge>
                                    <feMergeNode in="coloredBlur" />
                                    <feMergeNode in="SourceGraphic" />
                                </feMerge>
                            </filter>
                            <linearGradient id="arrowGradient1" x1="0%" y1="0%" x2="100%" y2="100%">
                                <stop offset="0%" stopColor="#f97316" />
                                <stop offset="100%" stopColor="#fb923c" />
                            </linearGradient>
                        </defs>

                        {isInView && modules.map((module, index) => {
                            const endX = centerX + module.position.x * moduleRadius
                            const endY = centerY + module.position.y * moduleRadius * 0.8
                            return (
                                <AnimatedArrow
                                    key={module.id}
                                    startX={centerX}
                                    startY={centerY}
                                    endX={endX}
                                    endY={endY}
                                    delay={index * 0.2}
                                    color="#f97316"
                                />
                            )
                        })}
                    </svg>

                    {/* Central Hub */}
                    <motion.div
                        className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 z-10"
                        initial={{ scale: 0, opacity: 0 }}
                        animate={isInView ? { scale: 1, opacity: 1 } : {}}
                        transition={{ duration: 0.6, type: "spring" }}
                    >
                        <div className="relative">
                            {/* Pulsing rings */}
                            <div className="absolute inset-0 rounded-full bg-primary/20 animate-ping" style={{ animationDuration: "2s" }} />
                            <div className="absolute inset-[-10px] rounded-full bg-primary/10 animate-ping" style={{ animationDuration: "2.5s", animationDelay: "0.5s" }} />

                            {/* Main hub */}
                            <div className="relative w-20 h-20 md:w-24 md:h-24 rounded-full bg-gradient-to-br from-primary to-aura-coral flex items-center justify-center shadow-2xl">
                                <div className="absolute inset-0 rounded-full bg-gradient-to-br from-primary to-aura-coral opacity-50 blur-xl" />
                                <Cpu className="h-10 w-10 md:h-12 md:w-12 text-white relative z-10" />
                            </div>
                        </div>
                    </motion.div>

                    {/* Module cards */}
                    {modules.map((module, index) => {
                        const xOffset = module.position.x === -1 ? "left-0 md:left-4" : "right-0 md:right-4"
                        const yOffset = module.position.y === -1 ? "top-0 md:top-8" : "bottom-0 md:bottom-8"

                        return (
                            <motion.div
                                key={module.id}
                                className={`absolute ${xOffset} ${yOffset} w-[calc(50%-60px)] md:w-[280px]`}
                                initial={{ opacity: 0, scale: 0.8, y: module.position.y * 30 }}
                                animate={isInView ? { opacity: 1, scale: 1, y: 0 } : {}}
                                transition={{ duration: 0.6, delay: 0.3 + index * 0.15 }}
                            >
                                <div className="group p-6 rounded-2xl bg-card/80 backdrop-blur-sm border border-border hover:border-primary/50 transition-all duration-300 hover:-translate-y-1 hover:shadow-xl">
                                    {/* Icon */}
                                    <div
                                        className={`w-14 h-14 rounded-xl bg-gradient-to-br ${module.color} flex items-center justify-center mb-4 group-hover:scale-110 transition-transform shadow-lg`}
                                        style={{ boxShadow: `0 0 30px ${module.glowColor}` }}
                                    >
                                        <module.icon className="h-7 w-7 text-white" />
                                    </div>

                                    {/* Text */}
                                    <h3 className="font-display text-xl font-bold mb-1">{module.title}</h3>
                                    <p className="text-sm text-primary font-medium mb-2">{module.subtitle}</p>
                                    <p className="text-sm text-muted-foreground">{module.description}</p>
                                </div>
                            </motion.div>
                        )
                    })}
                </div>
            </div>
        </section>
    )
}
